CREATE TABLE bookings (room_id int NOT NULL, during tstzrange NOT NULL, guest_id int, nights int GENERATED ALWAYS AS (upper(during)::date - lower(during)::date) VIRTUAL, CONSTRAINT bookings_pkey PRIMARY KEY (room_id, during WITHOUT OVERLAPS), CONSTRAINT bookings_room_fk FOREIGN KEY (room_id, PERIOD during) REFERENCES rooms (id, PERIOD valid_at), CONSTRAINT bookings_guest_check CHECK (guest_id > 0) NOT ENFORCED, CONSTRAINT bookings_guest_nn NOT NULL guest_id NO INHERIT);
